// Runtime of translated PowerPC applications: what the toolbox shims share.
#ifndef PPCRT_H
#define PPCRT_H
#include "ppc.h"
#include <stdio.h>
#include <stdlib.h>

#ifdef __OBJC__
#import <Foundation/Foundation.h>
#endif

// generated by liftppc.py
extern const PPCFunc ppc_funcs[];
extern const size_t ppc_nfuncs;
extern const char *const ppc_import_names[];
extern const unsigned char ppc_import_class[];
extern const size_t ppc_nimports;
extern const uint32_t ppc_main_tv, ppc_code_size, ppc_data_size;
extern const unsigned char ppc_code_bin[], ppc_data_bin[];

enum {
	CODE_BASE = 0x01000000,
	DATA_BASE = 0x02000000,
	IMPORT_TV = 0x00f00000,
	IMPORT_CODE = 0xff000000,
	LOWMEM_TOP = 0x00010000,
	HEAP_BASE = 0x04000000,
	HEAP_TOP = 0x70000000,
	STACK_TOP = 0x7f000000,
	STACK_SIZE = 0x00800000,
	HOSTCB_CODE = 0xfe000000,   // code addresses of host procedures handed to the guest
};

extern PPC *ppc_cpu;
extern int ppc_verbose;
void ppc_log(const char *fmt, ...) __attribute__((format(printf, 1, 2)));
const char *ppc_func_name(uint32_t addr);
void ppc_backtrace(PPC *c);

// shims: arguments by position (integers and pointers), results
typedef void (*Shim)(PPC *c);
static inline uint32_t ARG(PPC *c, int i) { return i < 8 ? c->r[3 + i] : LD32(c->r[1] + 24 + 4 * i); }
#define A(i) ARG(c, i)
#define RET(v) ((void)(c->r[3] = (uint32_t)(v)))
static inline void RET_OK(PPC *c) { c->r[3] = 0; }
static inline void RET_ERR(PPC *c, int e) { c->r[3] = (uint32_t)e; }
#define FRET(v) ((void)(c->f[1].d = (double)(v)))
void ppc_register_shims(const char *const *names, const Shim *fns, int n);
typedef struct { const char *name; Shim fn; } ShimDef;
void ppc_register(const ShimDef *d, int n);
#define REGISTER(T) __attribute__((constructor)) static void reg_##T(void) { ppc_register(T, (int)(sizeof T / sizeof *T)); }
#define S(n) {#n, sh_##n}

// calls into guest code: a transition vector (code, TOC) and integer arguments
uint32_t ppc_callback(uint32_t tvec, int n, const uint32_t *args);
uint32_t ppc_cb0(uint32_t tvec);
uint32_t ppc_cb1(uint32_t tvec, uint32_t a);
uint32_t ppc_cb2(uint32_t tvec, uint32_t a, uint32_t b);
uint32_t ppc_cb3(uint32_t tvec, uint32_t a, uint32_t b, uint32_t c);
uint32_t ppc_cb4(uint32_t tvec, uint32_t a, uint32_t b, uint32_t c, uint32_t d);
uint32_t ppc_cb5(uint32_t tvec, uint32_t a, uint32_t b, uint32_t c, uint32_t d, uint32_t e);
// a host procedure as a guest transition vector (for callbacks the guest calls)
uint32_t ppc_host_tvec(Shim fn);

// guest heap (mem.c)
uint32_t gmalloc(uint32_t n);
uint32_t gcalloc(uint32_t n);
void gfree(uint32_t p);
uint32_t gsize(uint32_t p);
uint32_t grealloc(uint32_t p, uint32_t n);
uint32_t gstrdup(const char *s);
uint32_t NewHandleG(uint32_t n);       // a handle with n bytes (uninitialized)
uint32_t NewHandleClearG(uint32_t n);
uint32_t NewHandleFrom(const void *p, uint32_t n);
void DisposeHandleG(uint32_t h);
uint32_t HSize(uint32_t h);
int HSetSize(uint32_t h, uint32_t n);
static inline uint32_t HP(uint32_t h) { return h ? LD32(h) : 0; }  // the handle's data
int is_handle(uint32_t h);
extern int16_t mem_err;

// guest strings
void p2c(uint32_t pstr, char *out, size_t n);          // Pascal string -> C
void c2p(const char *s, uint32_t pstr);                // C -> Pascal (at most 255)
#ifdef __OBJC__
NSString *pstr_ns(uint32_t pstr);                      // Mac Roman Pascal string
NSString *mac_ns(const void *bytes, size_t n);
void ns_pstr(NSString *s, uint32_t pstr);
#endif

// guest-visible tokens for host objects (WindowRef, ControlRef, ...): small
// guest blocks so the guest can compare them and keep them in its own structures
uint32_t tok_new(void *obj, uint32_t size, uint32_t tag);
void *tok_get(uint32_t t, uint32_t tag);
void tok_free(uint32_t t);

// rectangles and points in guest memory (QuickDraw: top, left, bottom, right)
typedef struct { int16_t top, left, bottom, right; } QRect;
typedef struct { int16_t v, h; } QPoint;
static inline QRect RECT(uint32_t a)
{
	QRect r = {(int16_t)LD16(a), (int16_t)LD16(a + 2), (int16_t)LD16(a + 4), (int16_t)LD16(a + 6)};
	return r;
}
static inline void PUTRECT(uint32_t a, QRect r) { ST16(a, r.top); ST16(a + 2, r.left); ST16(a + 4, r.bottom); ST16(a + 6, r.right); }
static inline QPoint PT(uint32_t v) { QPoint p = {(int16_t)(v >> 16), (int16_t)v}; return p; }   // a Point passed by value
static inline uint32_t PTV(QPoint p) { return ((uint32_t)(uint16_t)p.v << 16) | (uint16_t)p.h; }
static inline QPoint LDPT(uint32_t a) { QPoint p = {(int16_t)LD16(a), (int16_t)LD16(a + 2)}; return p; }
static inline void STPT(uint32_t a, QPoint p) { ST16(a, p.v); ST16(a + 2, p.h); }

#define FOURCC(a) ((uint32_t)(a))

// paths
extern char ppc_app_path[1024];     // the application file (its resource fork)
extern char ppc_app_dir[1024];

#endif
